CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_shopping_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, avatar_url) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', ''), NEW.raw_user_meta_data->>'avatar_url'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_shopping_profile() FROM PUBLIC;
CREATE TRIGGER shopping_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_shopping_profile();
INSERT INTO public.profiles(id, display_name, avatar_url) SELECT id, COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', ''), raw_user_meta_data->>'avatar_url' FROM auth.users ON CONFLICT (id) DO NOTHING;
CREATE TABLE public.shopping_lists (user_id uuid PRIMARY KEY, items jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.shopping_lists TO authenticated;
GRANT ALL ON public.shopping_lists TO service_role;
ALTER TABLE public.shopping_lists ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own shopping list" ON public.shopping_lists FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.maps_cache (user_id uuid NOT NULL, cache_key text NOT NULL, result jsonb NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(user_id, cache_key));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.maps_cache TO authenticated;
GRANT ALL ON public.maps_cache TO service_role;
ALTER TABLE public.maps_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own maps cache" ON public.maps_cache FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());